`timescale 1ns / 1ps
// axil_timer: 32-bit down-counting timer, one-shot and periodic modes,
// level interrupt, AXI4-Lite subordinate port.
// Implements interface_spec.md per microarchitecture.md.
module axil_timer #(
    parameter integer ADDR_WIDTH = 4
) (
    input  wire                  aclk,
    input  wire                  aresetn,
    input  wire [ADDR_WIDTH-1:0] s_axil_awaddr,
    input  wire                  s_axil_awvalid,
    output wire                  s_axil_awready,
    input  wire [31:0]           s_axil_wdata,
    input  wire [3:0]            s_axil_wstrb,
    input  wire                  s_axil_wvalid,
    output wire                  s_axil_wready,
    output reg  [1:0]            s_axil_bresp,
    output reg                   s_axil_bvalid,
    input  wire                  s_axil_bready,
    input  wire [ADDR_WIDTH-1:0] s_axil_araddr,
    input  wire                  s_axil_arvalid,
    output wire                  s_axil_arready,
    output reg  [31:0]           s_axil_rdata,
    output reg  [1:0]            s_axil_rresp,
    output reg                   s_axil_rvalid,
    input  wire                  s_axil_rready,
    output wire                  irq
);

  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  localparam [1:0] IDX_CTRL    = 2'd0;
  localparam [1:0] IDX_LOAD    = 2'd1;
  localparam [1:0] IDX_COUNT   = 2'd2;
  localparam [1:0] IDX_STATUS  = 2'd3;

  // ------------------------------------------------------------------
  // Timer state
  // ------------------------------------------------------------------
  reg        en;
  reg        ie;
  reg        mode;
  reg        expired;
  reg [31:0] load;
  reg [31:0] count;

  // ------------------------------------------------------------------
  // Write channel state
  // ------------------------------------------------------------------
  reg                  aw_held;
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg                  w_held;
  reg [31:0]           w_data_q;
  reg [3:0]            w_strb_q;

  assign s_axil_awready = !aw_held && !s_axil_bvalid;
  assign s_axil_wready  = !w_held && !s_axil_bvalid;

  wire aw_hs    = s_axil_awvalid && s_axil_awready;
  wire w_hs     = s_axil_wvalid && s_axil_wready;
  wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [31:0]           wr_data = w_held ? w_data_q : s_axil_wdata;
  wire [3:0]            wr_strb = w_held ? w_strb_q : s_axil_wstrb;

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) &&
                         ((wr_addr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] wr_idx    = wr_addr[3:2];
  wire       wr_ok     = wr_mapped && (wr_idx != IDX_COUNT);

  wire ctrl_we    = do_write && wr_ok && (wr_idx == IDX_CTRL) && wr_strb[0];
  wire load_we    = do_write && wr_ok && (wr_idx == IDX_LOAD);
  wire status_clr = do_write && wr_ok && (wr_idx == IDX_STATUS) &&
                    wr_strb[0] && wr_data[0];

  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held       <= 1'b0;
      aw_addr_q     <= {ADDR_WIDTH{1'b0}};
      w_held        <= 1'b0;
      w_data_q      <= 32'd0;
      w_strb_q      <= 4'd0;
      s_axil_bvalid <= 1'b0;
      s_axil_bresp  <= RESP_OKAY;
    end else begin
      if (do_write) begin
        aw_held       <= 1'b0;
        w_held        <= 1'b0;
        s_axil_bvalid <= 1'b1;
        s_axil_bresp  <= wr_ok ? RESP_OKAY : RESP_SLVERR;
      end else begin
        if (aw_hs) begin
          aw_held   <= 1'b1;
          aw_addr_q <= s_axil_awaddr;
        end
        if (w_hs) begin
          w_held   <= 1'b1;
          w_data_q <= s_axil_wdata;
          w_strb_q <= s_axil_wstrb;
        end
        if (s_axil_bvalid && s_axil_bready) begin
          s_axil_bvalid <= 1'b0;
        end
      end
    end
  end

  // ------------------------------------------------------------------
  // Read channel
  // ------------------------------------------------------------------
  assign s_axil_arready = !s_axil_rvalid;

  wire       ar_hs     = s_axil_arvalid && s_axil_arready;
  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) &&
                         ((s_axil_araddr >> 4) == {ADDR_WIDTH{1'b0}});
  wire [1:0] rd_idx    = s_axil_araddr[3:2];

  reg [31:0] rd_value;

  always @* begin
    rd_value = 32'd0;
    if (rd_mapped) begin
      case (rd_idx)
        IDX_CTRL:   rd_value = {29'd0, mode, ie, en};
        IDX_LOAD:   rd_value = load;
        IDX_COUNT:  rd_value = count;
        IDX_STATUS: rd_value = {31'd0, expired};
        default:    rd_value = 32'd0;
      endcase
    end
  end

  always @(posedge aclk) begin
    if (!aresetn) begin
      s_axil_rvalid <= 1'b0;
      s_axil_rdata  <= 32'd0;
      s_axil_rresp  <= RESP_OKAY;
    end else if (ar_hs) begin
      s_axil_rvalid <= 1'b1;
      s_axil_rdata  <= rd_value;
      s_axil_rresp  <= rd_mapped ? RESP_OKAY : RESP_SLVERR;
    end else if (s_axil_rvalid && s_axil_rready) begin
      s_axil_rvalid <= 1'b0;
    end
  end

  // ------------------------------------------------------------------
  // Timer next state (order gives the specified priorities)
  // ------------------------------------------------------------------
  wire count_end = en && (count[31:1] == 31'd0);

  reg        en_d;
  reg        ie_d;
  reg        mode_d;
  reg        expired_d;
  reg [31:0] load_d;
  reg [31:0] count_d;

  always @* begin
    en_d      = en;
    ie_d      = ie;
    mode_d    = mode;
    expired_d = expired;
    load_d    = load;
    count_d   = count;

    // 1. Count step: decrement, reload or stop.
    if (en) begin
      if (count_end) begin
        if (mode) begin
          count_d = load;
        end else begin
          count_d = 32'd0;
          en_d    = 1'b0;
        end
      end else begin
        count_d = count - 32'd1;
      end
    end

    // 2. Expired: clear first, then a count end sets it (end beats clear).
    if (status_clr) begin
      expired_d = 1'b0;
    end
    if (count_end) begin
      expired_d = 1'b1;
    end

    // 3. CTRL write wins for en and count.
    if (ctrl_we) begin
      ie_d   = wr_data[1];
      mode_d = wr_data[2];
      if (wr_data[0]) begin
        en_d    = 1'b1;
        count_d = load;
      end else begin
        en_d = 1'b0;
      end
    end

    // 4. LOAD write merges strobed bytes.
    if (load_we) begin
      if (wr_strb[0]) load_d[7:0]   = wr_data[7:0];
      if (wr_strb[1]) load_d[15:8]  = wr_data[15:8];
      if (wr_strb[2]) load_d[23:16] = wr_data[23:16];
      if (wr_strb[3]) load_d[31:24] = wr_data[31:24];
    end
  end

  always @(posedge aclk) begin
    if (!aresetn) begin
      en      <= 1'b0;
      ie      <= 1'b0;
      mode    <= 1'b0;
      expired <= 1'b0;
      load    <= 32'd0;
      count   <= 32'd0;
    end else begin
      en      <= en_d;
      ie      <= ie_d;
      mode    <= mode_d;
      expired <= expired_d;
      load    <= load_d;
      count   <= count_d;
    end
  end

  assign irq = expired && ie;

endmodule
=== END FILE ===
