`timescale 1ns / 1ps
// Self-checking testbench for axil_timer.
// Two lanes (ADDR_WIDTH 4 and 8) run concurrently; the top prints the verdict.

module axil_timer_tb_lane #(
    parameter integer AW   = 4,
    parameter integer HALF = 5
) (
    output reg [31:0] passed,
    output reg [31:0] failed,
    output reg        done
);

  localparam [7:0] A_CTRL   = 8'h00;
  localparam [7:0] A_LOAD   = 8'h04;
  localparam [7:0] A_COUNT  = 8'h08;
  localparam [7:0] A_STATUS = 8'h0C;
  localparam [1:0] OKAY     = 2'b00;
  localparam [1:0] SLVERR   = 2'b10;

  reg           clk;
  reg           rstn;
  reg  [AW-1:0] awaddr;
  reg           awvalid;
  wire          awready;
  reg  [31:0]   wdata;
  reg  [3:0]    wstrb;
  reg           wvalid;
  wire          wready;
  wire [1:0]    bresp;
  wire          bvalid;
  reg           bready;
  reg  [AW-1:0] araddr;
  reg           arvalid;
  wire          arready;
  wire [31:0]   rdata;
  wire [1:0]    rresp;
  wire          rvalid;
  reg           rready;
  wire          irq;

  axil_timer #(.ADDR_WIDTH(AW)) dut (
      .aclk           (clk),
      .aresetn        (rstn),
      .s_axil_awaddr  (awaddr),
      .s_axil_awvalid (awvalid),
      .s_axil_awready (awready),
      .s_axil_wdata   (wdata),
      .s_axil_wstrb   (wstrb),
      .s_axil_wvalid  (wvalid),
      .s_axil_wready  (wready),
      .s_axil_bresp   (bresp),
      .s_axil_bvalid  (bvalid),
      .s_axil_bready  (bready),
      .s_axil_araddr  (araddr),
      .s_axil_arvalid (arvalid),
      .s_axil_arready (arready),
      .s_axil_rdata   (rdata),
      .s_axil_rresp   (rresp),
      .s_axil_rvalid  (rvalid),
      .s_axil_rready  (rready),
      .irq            (irq)
  );

  initial clk = 1'b0;
  always #HALF clk = ~clk;

  // Edge counter and irq monitor. After rising edge k, cyc == k.
  // rise_edge is the edge after which irq rose.
  integer cyc;
  integer rises;
  integer falls;
  integer rise_edge;
  reg     irq_last;

  initial begin
    cyc       = 0;
    rises     = 0;
    falls     = 0;
    rise_edge = -1;
    irq_last  = 1'b0;
  end

  always @(posedge clk) begin
    if (irq === 1'b1 && irq_last === 1'b0) begin
      rises     = rises + 1;
      rise_edge = cyc;
    end
    if (irq === 1'b0 && irq_last === 1'b1) begin
      falls = falls + 1;
    end
    irq_last = irq;
    cyc      = cyc + 1;
  end

  // Results of the last transfer.
  reg [1:0]  g_resp;
  integer    g_eff;
  reg [31:0] g_rdata;
  reg [1:0]  g_rresp;
  integer    g_rhs;

  function [AW-1:0] ax(input [7:0] a);
    begin
      ax = a[AW-1:0];
    end
  endfunction

  task chk(input ok, input integer id);
    begin
      if (ok === 1'b1) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("axil_timer_tb AW=%0d: check %0d failed after edge %0d", AW, id, cyc);
      end
    end
  endtask

  task chk_eq(input [31:0] got, input [31:0] exp, input integer id);
    begin
      if (got === exp) begin
        passed = passed + 32'd1;
      end else begin
        failed = failed + 32'd1;
        $error("axil_timer_tb AW=%0d: check %0d failed after edge %0d: got 0x%08h, expected 0x%08h",
               AW, id, cyc, got, exp);
      end
    end
  endtask

  task tick(input integer n);
    integer i;
    begin
      for (i = 0; i < n; i = i + 1) @(negedge clk);
    end
  endtask

  task wait_cyc(input integer t);
    begin
      while (cyc < t) @(negedge clk);
    end
  endtask

  task wait_rise(input integer base, input integer timeout, input integer id);
    integer i;
    begin
      i = 0;
      while (rises == base && i < timeout) begin
        @(negedge clk);
        i = i + 1;
      end
      chk(rises != base, id);
    end
  endtask

  task do_reset;
    begin
      awvalid = 1'b0;
      wvalid  = 1'b0;
      arvalid = 1'b0;
      bready  = 1'b0;
      rready  = 1'b0;
      rstn    = 1'b0;
      tick(3);
      rstn    = 1'b1;
      @(negedge clk);
    end
  endtask

  task send_aw(input [7:0] addr);
    integer i;
    reg f;
    reg dn;
    begin
      awaddr  = ax(addr);
      awvalid = 1'b1;
      dn      = 1'b0;
      for (i = 0; i < 50 && !dn; i = i + 1) begin
        f = awready;
        @(negedge clk);
        if (f === 1'b1) dn = 1'b1;
      end
      awvalid = 1'b0;
      awaddr  = {AW{1'b0}};
      chk(dn, 9000);
    end
  endtask

  task send_w(input [31:0] data, input [3:0] strb);
    integer i;
    reg f;
    reg dn;
    begin
      wdata  = data;
      wstrb  = strb;
      wvalid = 1'b1;
      dn     = 1'b0;
      for (i = 0; i < 50 && !dn; i = i + 1) begin
        f = wready;
        @(negedge clk);
        if (f === 1'b1) dn = 1'b1;
      end
      wvalid = 1'b0;
      wdata  = 32'd0;
      wstrb  = 4'd0;
      chk(dn, 9001);
    end
  endtask

  // order: 0 AW and W together, 1 AW then W, 2 W then AW.
  // gap: idle cycles between the halves. bstall: cycles BREADY is held low.
  task axi_write(input [7:0] addr, input [31:0] data, input [3:0] strb,
                 input integer order, input integer gap, input integer bstall,
                 output [1:0] resp, output integer eff);
    integer i;
    reg aw_f;
    reg w_f;
    reg aw_dn;
    reg w_dn;
    begin
      bready = 1'b0;
      resp   = 2'b11;
      eff    = -1;
      if (order == 1) begin
        send_aw(addr);
        for (i = 0; i < gap; i = i + 1) begin
          chk(bvalid === 1'b0 && awready === 1'b0 && wready === 1'b1, 9006);
          @(negedge clk);
        end
        send_w(data, strb);
      end else if (order == 2) begin
        send_w(data, strb);
        for (i = 0; i < gap; i = i + 1) begin
          chk(bvalid === 1'b0 && awready === 1'b1 && wready === 1'b0, 9007);
          @(negedge clk);
        end
        send_aw(addr);
      end else begin
        awaddr  = ax(addr);
        awvalid = 1'b1;
        wdata   = data;
        wstrb   = strb;
        wvalid  = 1'b1;
        aw_dn   = 1'b0;
        w_dn    = 1'b0;
        for (i = 0; i < 50 && !(aw_dn && w_dn); i = i + 1) begin
          aw_f = awvalid & awready;
          w_f  = wvalid & wready;
          @(negedge clk);
          if (aw_f === 1'b1) begin
            awvalid = 1'b0;
            awaddr  = {AW{1'b0}};
            aw_dn   = 1'b1;
          end
          if (w_f === 1'b1) begin
            wvalid = 1'b0;
            wdata  = 32'd0;
            wstrb  = 4'd0;
            w_dn   = 1'b1;
          end
        end
        chk(aw_dn && w_dn, 9002);
      end
      chk(bvalid === 1'b1, 9003);
      eff  = cyc;
      resp = bresp;
      for (i = 0; i < bstall; i = i + 1) begin
        @(negedge clk);
        chk(bvalid === 1'b1 && bresp === resp && awready === 1'b0 && wready === 1'b0, 9004);
      end
      bready = 1'b1;
      @(negedge clk);
      bready = 1'b0;
      chk(bvalid === 1'b0, 9005);
    end
  endtask

  // hs: the edge on which the read address was accepted.
  task axi_read(input [7:0] addr, input integer rstall,
                output [31:0] data, output [1:0] resp, output integer hs);
    integer i;
    reg f;
    reg dn;
    begin
      rready  = 1'b0;
      araddr  = ax(addr);
      arvalid = 1'b1;
      dn      = 1'b0;
      hs      = -1;
      for (i = 0; i < 50 && !dn; i = i + 1) begin
        f = arready;
        @(negedge clk);
        if (f === 1'b1) dn = 1'b1;
      end
      arvalid = 1'b0;
      araddr  = {AW{1'b0}};
      chk(dn, 9010);
      hs = cyc;
      chk(rvalid === 1'b1, 9011);
      data = rdata;
      resp = rresp;
      for (i = 0; i < rstall; i = i + 1) begin
        @(negedge clk);
        chk(rvalid === 1'b1 && rdata === data && rresp === resp && arready === 1'b0, 9012);
      end
      rready = 1'b1;
      @(negedge clk);
      rready = 1'b0;
      chk(rvalid === 1'b0, 9013);
    end
  endtask

  task wr(input [7:0] addr, input [31:0] data, input [3:0] strb,
          input [1:0] exp_resp, input integer id);
    begin
      axi_write(addr, data, strb, 0, 0, 0, g_resp, g_eff);
      chk_eq({30'd0, g_resp}, {30'd0, exp_resp}, id);
    end
  endtask

  task rd_chk(input [7:0] addr, input [31:0] exp, input [1:0] exp_resp, input integer id);
    begin
      axi_read(addr, 0, g_rdata, g_rresp, g_rhs);
      chk_eq(g_rdata, exp, id);
      chk_eq({30'd0, g_rresp}, {30'd0, exp_resp}, id);
    end
  endtask

  task oneshot_test(input [31:0] n, input integer id);
    integer e1;
    integer b1;
    integer len;
    begin
      len = (n == 32'd0) ? 1 : n;
      wr(A_STATUS, 32'h1, 4'h1, OKAY, id);
      wr(A_LOAD, n, 4'hF, OKAY, id + 1);
      chk(irq === 1'b0, id + 2);
      b1 = rises;
      wr(A_CTRL, 32'h3, 4'h1, OKAY, id + 3);
      e1 = g_eff;
      wait_rise(b1, len + 20, id + 4);
      chk_eq(rise_edge - e1, len, id + 5);
      chk(rises == b1 + 1, id + 6);
      rd_chk(A_CTRL, 32'h2, OKAY, id + 7);
      rd_chk(A_COUNT, 32'h0, OKAY, id + 8);
      rd_chk(A_STATUS, 32'h1, OKAY, id + 9);
      wr(A_STATUS, 32'h1, 4'b1110, OKAY, id + 10);
      wr(A_STATUS, 32'h0, 4'hF, OKAY, id + 11);
      rd_chk(A_STATUS, 32'h1, OKAY, id + 12);
      chk(irq === 1'b1, id + 13);
      wr(A_STATUS, 32'h1, 4'h1, OKAY, id + 14);
      chk(irq === 1'b0, id + 15);
      b1 = rises;
      tick(2 * len + 10);
      chk(rises == b1 && irq === 1'b0, id + 16);
      rd_chk(A_STATUS, 32'h0, OKAY, id + 17);
      rd_chk(A_COUNT, 32'h0, OKAY, id + 18);
      rd_chk(A_CTRL, 32'h2, OKAY, id + 19);
    end
  endtask

  integer    e;
  integer    s;
  integer    j;
  integer    base_r;
  integer    base_f;
  reg [31:0] expv;

  initial begin
    passed  = 32'd0;
    failed  = 32'd0;
    done    = 1'b0;
    rstn    = 1'b0;
    awaddr  = {AW{1'b0}};
    awvalid = 1'b0;
    wdata   = 32'd0;
    wstrb   = 4'd0;
    wvalid  = 1'b0;
    bready  = 1'b0;
    araddr  = {AW{1'b0}};
    arvalid = 1'b0;
    rready  = 1'b0;
    @(negedge clk);
    do_reset;

    // T1: reset values
    chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1 &&
        bvalid === 1'b0 && rvalid === 1'b0 && irq === 1'b0, 1);
    rd_chk(A_CTRL,   32'h0, OKAY, 2);
    rd_chk(A_LOAD,   32'h0, OKAY, 3);
    rd_chk(A_COUNT,  32'h0, OKAY, 4);
    rd_chk(A_STATUS, 32'h0, OKAY, 5);

    // T2: LOAD with partial and empty strobes
    wr(A_LOAD, 32'hFFFF_FFFF, 4'hF, OKAY, 10);
    rd_chk(A_LOAD, 32'hFFFF_FFFF, OKAY, 11);
    wr(A_LOAD, 32'h1122_3344, 4'b0101, OKAY, 12);
    rd_chk(A_LOAD, 32'hFF22_FF44, OKAY, 13);
    wr(A_LOAD, 32'hAABB_CCDD, 4'b1010, OKAY, 14);
    rd_chk(A_LOAD, 32'hAA22_CC44, OKAY, 15);
    wr(A_LOAD, 32'h0000_0000, 4'b0000, OKAY, 16);
    rd_chk(A_LOAD, 32'hAA22_CC44, OKAY, 17);

    // T3: channel orders and backpressure
    axi_write(A_LOAD, 32'h0000_1234, 4'hF, 1, 3, 0, g_resp, g_eff);
    chk_eq({30'd0, g_resp}, {30'd0, OKAY}, 20);
    rd_chk(A_LOAD, 32'h0000_1234, OKAY, 21);
    axi_write(A_LOAD, 32'h0000_5678, 4'hF, 2, 4, 0, g_resp, g_eff);
    chk_eq({30'd0, g_resp}, {30'd0, OKAY}, 22);
    rd_chk(A_LOAD, 32'h0000_5678, OKAY, 23);
    axi_write(A_LOAD, 32'h0000_9ABC, 4'hF, 0, 0, 6, g_resp, g_eff);
    chk_eq({30'd0, g_resp}, {30'd0, OKAY}, 24);
    rd_chk(A_LOAD, 32'h0000_9ABC, OKAY, 25);
    axi_write(A_COUNT, 32'h0000_0001, 4'hF, 1, 2, 4, g_resp, g_eff);
    chk_eq({30'd0, g_resp}, {30'd0, SLVERR}, 26);
    rd_chk(A_COUNT, 32'h0, OKAY, 27);
    axi_write(A_STATUS, 32'h0000_0001, 4'h1, 2, 0, 3, g_resp, g_eff);
    chk_eq({30'd0, g_resp}, {30'd0, OKAY}, 28);
    axi_read(A_LOAD, 5, g_rdata, g_rresp, g_rhs);
    chk_eq(g_rdata, 32'h0000_9ABC, 29);
    chk_eq({30'd0, g_rresp}, {30'd0, OKAY}, 30);
    axi_read(8'h06, 3, g_rdata, g_rresp, g_rhs);
    chk_eq(g_rdata, 32'h0, 31);
    chk_eq({30'd0, g_rresp}, {30'd0, SLVERR}, 32);

    // T4: COUNT read only, SLVERR policy, no aliasing
    wr(A_COUNT, 32'hDEAD_BEEF, 4'hF, SLVERR, 40);
    rd_chk(A_COUNT, 32'h0, OKAY, 41);
    wr(8'h01, 32'h0000_0007, 4'hF, SLVERR, 42);
    wr(8'h02, 32'h0000_0007, 4'hF, SLVERR, 43);
    wr(8'h03, 32'h0000_0007, 4'hF, SLVERR, 44);
    wr(8'h05, 32'h5555_5555, 4'hF, SLVERR, 45);
    wr(8'h0E, 32'h0000_0001, 4'hF, SLVERR, 46);
    rd_chk(A_CTRL,   32'h0,         OKAY, 47);
    rd_chk(A_LOAD,   32'h0000_9ABC, OKAY, 48);
    rd_chk(A_STATUS, 32'h0,         OKAY, 49);
    rd_chk(8'h01, 32'h0, SLVERR, 50);
    rd_chk(8'h05, 32'h0, SLVERR, 51);
    rd_chk(8'h0A, 32'h0, SLVERR, 52);
    rd_chk(8'h0F, 32'h0, SLVERR, 53);
    if (AW > 4) begin
      wr(8'h10, 32'h0000_0007, 4'hF, SLVERR, 60);
      wr(8'h14, 32'h5555_5555, 4'hF, SLVERR, 61);
      wr(8'h18, 32'h0000_0001, 4'hF, SLVERR, 62);
      wr(8'h1C, 32'h0000_0001, 4'h1, SLVERR, 63);
      wr(8'h44, 32'h5555_5555, 4'hF, SLVERR, 64);
      wr(8'hF0, 32'h0000_0007, 4'hF, SLVERR, 65);
      wr(8'hFC, 32'h0000_0001, 4'hF, SLVERR, 66);
      rd_chk(A_CTRL,   32'h0,         OKAY, 67);
      rd_chk(A_LOAD,   32'h0000_9ABC, OKAY, 68);
      rd_chk(A_COUNT,  32'h0,         OKAY, 69);
      rd_chk(A_STATUS, 32'h0,         OKAY, 70);
      rd_chk(8'h10, 32'h0, SLVERR, 71);
      rd_chk(8'h14, 32'h0, SLVERR, 72);
      rd_chk(8'h18, 32'h0, SLVERR, 73);
      rd_chk(8'h1C, 32'h0, SLVERR, 74);
      rd_chk(8'h84, 32'h0, SLVERR, 75);
      rd_chk(8'hFC, 32'h0, SLVERR, 76);
    end

    // T5: CTRL write without wstrb[0] changes nothing
    wr(A_CTRL, 32'h0000_0007, 4'b1110, OKAY, 80);
    rd_chk(A_CTRL, 32'h0, OKAY, 81);
    tick(5);
    rd_chk(A_COUNT, 32'h0, OKAY, 82);
    chk(irq === 1'b0, 83);

    // T6: one-shot counts timed to the cycle
    oneshot_test(32'd1,    100);
    oneshot_test(32'd2,    130);
    oneshot_test(32'd5,    160);
    oneshot_test(32'd37,   190);
    oneshot_test(32'd0,    220);
    oneshot_test(32'd1000, 250);

    // T7: interrupt enable on a pending expiry
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 400);
    wr(A_LOAD, 32'd8, 4'hF, OKAY, 401);
    base_r = rises;
    base_f = falls;
    wr(A_CTRL, 32'h1, 4'h1, OKAY, 402);
    e = g_eff;
    wait_cyc(e + 12);
    chk(irq === 1'b0 && rises == base_r, 403);
    rd_chk(A_STATUS, 32'h1, OKAY, 404);
    rd_chk(A_CTRL,   32'h0, OKAY, 405);
    wr(A_CTRL, 32'h2, 4'h1, OKAY, 406);
    s = g_eff;
    wait_rise(base_r, 5, 407);
    chk_eq(rise_edge - s, 0, 408);
    wr(A_CTRL, 32'h0, 4'h1, OKAY, 409);
    chk(irq === 1'b0 && falls == base_f + 1, 410);
    rd_chk(A_STATUS, 32'h1, OKAY, 411);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 412);
    rd_chk(A_STATUS, 32'h0, OKAY, 413);

    // T8a: periodic, LOAD 10, with a clear landing on a count end
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 500);
    wr(A_LOAD, 32'd10, 4'hF, OKAY, 501);
    base_r = rises;
    base_f = falls;
    wr(A_CTRL, 32'h7, 4'h1, OKAY, 502);
    e = g_eff;
    wait_rise(base_r, 30, 503);
    chk_eq(rise_edge - e, 10, 504);
    wait_cyc(e + 19);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 505);
    chk_eq(g_eff - e, 20, 506);
    rd_chk(A_STATUS, 32'h1, OKAY, 507);
    chk(irq === 1'b1 && falls == base_f && rises == base_r + 1, 508);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 509);
    chk(irq === 1'b0, 510);
    wait_rise(base_r + 1, 30, 511);
    chk_eq(rise_edge - e, 30, 512);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 513);
    wait_rise(base_r + 2, 30, 514);
    chk_eq(rise_edge - e, 40, 515);
    rd_chk(A_CTRL, 32'h7, OKAY, 516);
    axi_read(A_COUNT, 0, g_rdata, g_rresp, g_rhs);
    j = g_rhs - 1 - e;
    chk_eq(g_rdata, 10 - (j % 10), 517);
    wr(A_CTRL, 32'h0, 4'h1, OKAY, 518);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 519);
    rd_chk(A_STATUS, 32'h0, OKAY, 520);

    // T8b: periodic, LOAD 0 counts as 1 (every edge ends a count)
    wr(A_LOAD, 32'd0, 4'hF, OKAY, 530);
    base_r = rises;
    wr(A_CTRL, 32'h7, 4'h1, OKAY, 531);
    e = g_eff;
    wait_rise(base_r, 10, 532);
    chk_eq(rise_edge - e, 1, 533);
    rd_chk(A_COUNT, 32'h0, OKAY, 534);
    rd_chk(A_CTRL,  32'h7, OKAY, 535);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 536);
    rd_chk(A_STATUS, 32'h1, OKAY, 537);
    chk(irq === 1'b1 && rises == base_r + 1, 538);
    wr(A_CTRL, 32'h0, 4'h1, OKAY, 539);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 540);
    rd_chk(A_STATUS, 32'h0, OKAY, 541);
    chk(irq === 1'b0, 542);

    // T8c: periodic, LOAD 300, three periods
    wr(A_LOAD, 32'd300, 4'hF, OKAY, 550);
    base_r = rises;
    wr(A_CTRL, 32'h7, 4'h1, OKAY, 551);
    e = g_eff;
    wait_rise(base_r, 320, 552);
    chk_eq(rise_edge - e, 300, 553);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 554);
    wait_rise(base_r + 1, 320, 555);
    chk_eq(rise_edge - e, 600, 556);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 557);
    wait_rise(base_r + 2, 320, 558);
    chk_eq(rise_edge - e, 900, 559);
    wr(A_CTRL, 32'h0, 4'h1, OKAY, 560);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 561);
    chk(irq === 1'b0, 562);

    // T9: read COUNT under backpressure while counting; stop freezes COUNT
    wr(A_LOAD, 32'd200, 4'hF, OKAY, 600);
    base_r = rises;
    wr(A_CTRL, 32'h1, 4'h1, OKAY, 601);
    e = g_eff;
    wait_cyc(e + 20);
    axi_read(A_COUNT, 6, g_rdata, g_rresp, g_rhs);
    chk_eq(g_rdata, 200 - (g_rhs - 1 - e), 602);
    wait_cyc(e + 50);
    wr(A_CTRL, 32'h0, 4'h1, OKAY, 603);
    s = g_eff;
    expv = 200 - (s - e);
    tick(20);
    rd_chk(A_COUNT, expv, OKAY, 604);
    rd_chk(A_CTRL, 32'h0, OKAY, 605);
    wr(A_COUNT, 32'h0000_1234, 4'hF, SLVERR, 606);
    tick(250);
    rd_chk(A_COUNT, expv, OKAY, 607);
    rd_chk(A_STATUS, 32'h0, OKAY, 608);
    chk(rises == base_r && irq === 1'b0, 609);

    // T10: restart while counting
    wr(A_LOAD, 32'd30, 4'hF, OKAY, 620);
    base_r = rises;
    wr(A_CTRL, 32'h3, 4'h1, OKAY, 621);
    e = g_eff;
    wait_cyc(e + 10);
    wr(A_CTRL, 32'h3, 4'h1, OKAY, 622);
    s = g_eff;
    wait_rise(base_r, 60, 623);
    chk_eq(rise_edge - s, 30, 624);
    chk(rises == base_r + 1, 625);
    rd_chk(A_CTRL, 32'h2, OKAY, 626);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 627);

    // T11a: restart landing on the edge a count ends
    wr(A_LOAD, 32'd10, 4'hF, OKAY, 640);
    base_r = rises;
    wr(A_CTRL, 32'h3, 4'h1, OKAY, 641);
    e = g_eff;
    wait_cyc(e + 9);
    wr(A_CTRL, 32'h3, 4'h1, OKAY, 642);
    chk_eq(g_eff - e, 10, 643);
    wait_rise(base_r, 10, 644);
    chk_eq(rise_edge - e, 10, 645);
    rd_chk(A_CTRL, 32'h3, OKAY, 646);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 647);
    chk(irq === 1'b0, 648);
    wait_rise(base_r + 1, 20, 649);
    chk_eq(rise_edge - e, 20, 650);
    rd_chk(A_CTRL, 32'h2, OKAY, 651);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 652);

    // T11b: periodic stop landing on the edge a count ends
    base_r = rises;
    wr(A_CTRL, 32'h7, 4'h1, OKAY, 660);
    e = g_eff;
    wait_cyc(e + 9);
    wr(A_CTRL, 32'h6, 4'h1, OKAY, 661);
    chk_eq(g_eff - e, 10, 662);
    rd_chk(A_COUNT,  32'd10, OKAY, 663);
    rd_chk(A_CTRL,   32'h6,  OKAY, 664);
    rd_chk(A_STATUS, 32'h1,  OKAY, 665);
    tick(30);
    rd_chk(A_COUNT, 32'd10, OKAY, 666);
    chk(rises == base_r + 1 && irq === 1'b1, 667);
    wr(A_CTRL, 32'h0, 4'h1, OKAY, 668);
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 669);
    chk(irq === 1'b0, 670);

    // T12: a read and a write accepted on the same clock
    wr(A_LOAD, 32'hA5A5_0001, 4'hF, OKAY, 700);
    chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1, 701);
    bready  = 1'b0;
    rready  = 1'b0;
    awaddr  = ax(A_LOAD);
    awvalid = 1'b1;
    wdata   = 32'h0000_0BEE;
    wstrb   = 4'hF;
    wvalid  = 1'b1;
    araddr  = ax(A_LOAD);
    arvalid = 1'b1;
    @(negedge clk);
    awvalid = 1'b0;
    wvalid  = 1'b0;
    arvalid = 1'b0;
    awaddr  = {AW{1'b0}};
    araddr  = {AW{1'b0}};
    wdata   = 32'd0;
    wstrb   = 4'd0;
    chk(bvalid === 1'b1 && rvalid === 1'b1, 702);
    chk_eq(rdata, 32'hA5A5_0001, 703);
    chk_eq({30'd0, bresp}, {30'd0, OKAY}, 704);
    chk_eq({30'd0, rresp}, {30'd0, OKAY}, 705);
    bready = 1'b1;
    rready = 1'b1;
    @(negedge clk);
    bready = 1'b0;
    rready = 1'b0;
    chk(bvalid === 1'b0 && rvalid === 1'b0, 706);
    rd_chk(A_LOAD, 32'h0000_0BEE, OKAY, 707);

    // T13: reset during a count, with a write address held
    wr(A_STATUS, 32'h1, 4'h1, OKAY, 800);
    wr(A_LOAD, 32'd40, 4'hF, OKAY, 801);
    wr(A_CTRL, 32'h7, 4'h1, OKAY, 802);
    e = g_eff;
    wait_cyc(e + 10);
    send_aw(A_LOAD);
    chk(awready === 1'b0 && wready === 1'b1 && bvalid === 1'b0, 803);
    base_r = rises;
    rstn = 1'b0;
    tick(2);
    rstn = 1'b1;
    chk(awready === 1'b1 && wready === 1'b1 && arready === 1'b1 &&
        bvalid === 1'b0 && rvalid === 1'b0 && irq === 1'b0, 804);
    rd_chk(A_CTRL,   32'h0, OKAY, 805);
    rd_chk(A_LOAD,   32'h0, OKAY, 806);
    rd_chk(A_COUNT,  32'h0, OKAY, 807);
    rd_chk(A_STATUS, 32'h0, OKAY, 808);
    send_w(32'h0000_1111, 4'hF);
    for (j = 0; j < 3; j = j + 1) begin
      chk(bvalid === 1'b0 && awready === 1'b1 && wready === 1'b0, 809);
      @(negedge clk);
    end
    send_aw(A_LOAD);
    chk(bvalid === 1'b1 && bresp === OKAY, 810);
    bready = 1'b1;
    @(negedge clk);
    bready = 1'b0;
    chk(bvalid === 1'b0, 811);
    rd_chk(A_LOAD, 32'h0000_1111, OKAY, 812);
    tick(100);
    chk(rises == base_r && irq === 1'b0, 813);
    rd_chk(A_COUNT, 32'h0, OKAY, 814);
    rd_chk(A_CTRL,  32'h0, OKAY, 815);

    done = 1'b1;
  end

endmodule

module axil_timer_tb;

  wire [31:0] p4;
  wire [31:0] f4;
  wire [31:0] p8;
  wire [31:0] f8;
  wire        d4;
  wire        d8;

  reg [8*64-1:0] nonce;
  reg [31:0]     total_p;
  reg [31:0]     total_f;
  integer        got;
  integer        t;

  axil_timer_tb_lane #(.AW(4), .HALF(5)) lane_aw4 (.passed(p4), .failed(f4), .done(d4));
  axil_timer_tb_lane #(.AW(8), .HALF(5)) lane_aw8 (.passed(p8), .failed(f8), .done(d8));

  initial begin
    nonce = {64{8'h00}};
    got   = $value$plusargs("nirmaan_nonce=%s", nonce);
    t     = 0;
    while (!(d4 === 1'b1 && d8 === 1'b1) && t < 200000) begin
      #100;
      t = t + 1;
    end
    total_p = p4 + p8;
    total_f = f4 + f8;
    if (!(d4 === 1'b1 && d8 === 1'b1)) begin
      $error("axil_timer_tb: watchdog expired before both lanes finished");
      total_f = total_f + 32'd1;
    end
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, total_p, total_f);
    $finish;
  end

endmodule
